import { PageContainer } from '../components/common/PageContainer'
import { invoke } from '../hooks/useIPC'

interface FolderSetting {
  key: string
  label: string
  description: string
  value: string
}

const FOLDER_SETTINGS: Array<{ key: string; label: string; description: string }> = [
  {
    key: 'fits_master_folder',
    label: 'Master FITS Folder',
    description: 'Root folder containing your astrophotography FITS files. Used as the default path in the FITS Analyzer.'
  },
  {
    key: 'base_folder_path',
    label: 'Base Folder Path',
    description: 'Root folder for generated target directory structures (lights, darks, flats, biases).'
  }
]

export function Settings(): React.ReactElement {
  const [folders, setFolders] = useState<FolderSetting[]>([])
  const [saving, setSaving] = useState<string | null>(null)

  useEffect(() => {
    loadSettings()
  }, [])

  async function loadSettings(): Promise<void> {
    const results = await Promise.all(
      FOLDER_SETTINGS.map(async (s) => {
        const result = await invoke<{ value: string | null }>('settings:get', { key: s.key })
        return { ...s, value: result.value ?? '' }
      })
    )
    setFolders(results)
  }

  async function handleBrowse(key: string): Promise<void> {
    const result = await invoke<{ path: string | null }>('settings:pick-folder')
    if (!result.path) return

    setSaving(key)
    await invoke('settings:set', { key, value: result.path })
    setFolders(prev => prev.map(f => f.key === key ? { ...f, value: result.path! } : f))
    setSaving(null)
  }

  async function handleClear(key: string): Promise<void> {
    setSaving(key)
    await invoke('settings:set', { key, value: '' })
    setFolders(prev => prev.map(f => f.key === key ? { ...f, value: '' } : f))
    setSaving(null)
  }

  return (
    <PageContainer title="Settings" subtitle="Configure your observatory application">
      <div className="space-y-6 max-w-2xl">
        <div className="bg-astro-surface border border-astro-border rounded-lg p-4">
          <h2 className="text-sm font-semibold text-astro-muted uppercase tracking-wider mb-4">Folder Paths</h2>
          <div className="space-y-5">
            {folders.map((folder) => (
              <div key={folder.key}>
                <label className="block text-sm font-medium text-astro-text mb-1">{folder.label}</label>
                <p className="text-xs text-astro-muted mb-2">{folder.description}</p>
                <div className="flex gap-2">
                  <div className="flex-1 bg-astro-bg border border-astro-border rounded px-3 py-2 text-sm text-astro-text truncate min-h-[38px] flex items-center">
                    {folder.value || <span className="text-astro-muted italic">Not set</span>}
                  </div>
                  <button
                    onClick={() => handleBrowse(folder.key)}
                    disabled={saving === folder.key}
                    className="px-4 py-2 bg-astro-accent text-white text-sm rounded hover:bg-astro-accent/80 transition-colors disabled:opacity-50"
                  >
                    Browse
                  </button>
                  {folder.value && (
                    <button
                      onClick={() => handleClear(folder.key)}
                      disabled={saving === folder.key}
                      className="px-3 py-2 border border-astro-border text-astro-muted text-sm rounded hover:text-astro-danger hover:border-astro-danger transition-colors disabled:opacity-50"
                    >
                      Clear
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </PageContainer>
  )
}
"}

Write {"file_path":"D:\code\astrorepo\src\renderer\components\fits\ScanControls.tsx","content":"import React, { useState, useEffect } from 'react'
import { invoke } from '../../hooks/useIPC'

interface ScanControlsProps {
  onScanComplete: () => void
}

export function ScanControls({ onScanComplete }: ScanControlsProps): React.ReactElement {
  const [folderPath, setFolderPath] = useState('')
  const [scanning, setScanning] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    invoke<{ value: string | null }>('settings:get', { key: 'fits_master_folder' }).then((r) => {
      if (r.value) setFolderPath(r.value)
    })
  }, [])

  async function handleBrowse(): Promise<void> {
    const result = await invoke<{ path: string | null }>('fits:pick-folder')
    if (result.path) setFolderPath(result.path)
  }

  async function handleScan(): Promise<void> {
    if (!folderPath) return
    setScanning(true)
    setError(null)
    try {
      await invoke('fits:start-scan', { folder_path: folderPath })
      onScanComplete()
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err))
    } finally {
      setScanning(false)
    }
  }

  return (
    <div className="bg-astro-surface border border-astro-border rounded-lg p-4">
      <h2 className="text-sm font-semibold text-astro-muted uppercase tracking-wider mb-3">Scan Folder</h2>
      <div className="flex gap-2">
        <div className="flex-1 bg-astro-bg border border-astro-border rounded px-3 py-2 text-sm text-astro-text truncate flex items-center min-h-[38px]">
          {folderPath || <span className="text-astro-muted italic">Select a folder...</span>}
        </div>
        <button
          onClick={handleBrowse}
          disabled={scanning}
          className="px-4 py-2 border border-astro-border text-astro-text text-sm rounded hover:bg-astro-bg transition-colors disabled:opacity-50"
        >
          Browse
        </button>
        <button
          onClick={handleScan}
          disabled={!folderPath || scanning}
          className="px-4 py-2 bg-astro-accent text-white text-sm rounded hover:bg-astro-accent/80 transition-colors disabled:opacity-50"
        >
          {scanning ? 'Scanning...' : 'Scan'}
        </button>
      </div>
      {error && <p className="text-astro-danger text-sm mt-2">{error}</p>}
    </div>
  )
}
"}

Write {"file_path":"D:\code\astrorepo\src\renderer\components\fits\ScanHistory.tsx","content":"import React from 'react'
import type { FitsScanSummary } from '@shared/types'
import { invoke } from '../../hooks/useIPC'

interface ScanHistoryProps {
  scans: FitsScanSummary[]
  selectedScanId: string | null
  onSelectScan: (id: string) => void
  onRefresh: () => void
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`
}

function formatDate(iso: string): string {
  const d = new Date(iso)
  return d.toLocaleDateString() + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

function statusBadge(status: string): React.ReactElement {
  const colors: Record<string, string> = {
    completed: 'bg-astro-success/20 text-astro-success',
    running: 'bg-astro-warning/20 text-astro-warning',
    failed: 'bg-astro-danger/20 text-astro-danger'
  }
  return (
    <span className={`px-2 py-0.5 rounded text-xs font-medium ${colors[status] ?? 'bg-astro-bg text-astro-muted'}`}>
      {status}
    </span>
  )
}

export function ScanHistory({ scans, selectedScanId, onSelectScan, onRefresh }: ScanHistoryProps): React.ReactElement {
  async function handleDelete(e: React.MouseEvent, scanId: string): Promise<void> {
    e.stopPropagation()
    await invoke('fits:delete-scan', { id: scanId })
    onRefresh()
  }

  if (scans.length === 0) {
    return (
      <div className="bg-astro-surface border border-astro-border rounded-lg p-4">
        <p className="text-sm text-astro-muted">No scans yet. Select a folder and click Scan to get started.</p>
      </div>
    )
  }

  return (
    <div className="bg-astro-surface border border-astro-border rounded-lg overflow-hidden">
      <div className="px-4 py-3 border-b border-astro-border">
        <h2 className="text-sm font-semibold text-astro-muted uppercase tracking-wider">Scan History</h2>
      </div>
      <div className="divide-y divide-astro-border">
        {scans.map((scan) => (
          <div
            key={scan.id}
            onClick={() => onSelectScan(scan.id)}
            className={`px-4 py-3 cursor-pointer transition-colors flex items-center justify-between ${
              selectedScanId === scan.id
                ? 'bg-astro-accent/10 border-l-2 border-astro-accent'
                : 'hover:bg-astro-bg/50'
            }`}
          >
            <div className="min-w-0 flex-1">
              <p className="text-sm text-astro-text truncate">{scan.folderPath}</p>
              <div className="flex gap-3 mt-1 text-xs text-astro-muted">
                <span>{scan.fileCount} files</span>
                <span>{formatSize(scan.totalSizeBytes)}</span>
                <span>{formatDate(scan.startedAt)}</span>
              </div>
            </div>
            <div className="flex items-center gap-2 ml-3 shrink-0">
              {statusBadge(scan.status)}
              <button
                onClick={(e) => handleDelete(e, scan.id)}
                className="text-astro-muted hover:text-astro-danger transition-colors p-1"
                title="Delete scan"
              >
                &times;
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
"}

Write {"file_path":"D:\code\astrorepo\src\renderer\components\fits\AggregateView.tsx","content":"import React from 'react'
import type { FitsScanAggregates } from '@shared/types'

interface AggregateViewProps {
  aggregates: FitsScanAggregates
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`
}

function formatExposure(sec: number): string {
  if (sec < 60) return `${sec.toFixed(0)}s`
  if (sec < 3600) return `${(sec / 60).toFixed(1)}m`
  return `${(sec / 3600).toFixed(1)}h`
}

function StatCard({ label, value, accent }: { label: string; value: string | number; accent?: boolean }): React.ReactElement {
  return (
    <div className="bg-astro-bg border border-astro-border rounded-lg p-3">
      <p className="text-xs text-astro-muted uppercase tracking-wider">{label}</p>
      <p className={`text-xl font-bold mt-1 ${accent ? 'text-astro-accent' : 'text-astro-text'}`}>{value}</p>
    </div>
  )
}

function BreakdownCard({ title, data }: { title: string; data: Record<string, number> }): React.ReactElement | null {
  const entries = Object.entries(data).sort(([, a], [, b]) => b - a)
  if (entries.length === 0) return null

  return (
    <div className="bg-astro-bg border border-astro-border rounded-lg p-3">
      <h3 className="text-xs text-astro-muted uppercase tracking-wider mb-2">{title}</h3>
      <div className="space-y-1.5">
        {entries.map(([name, count]) => (
          <div key={name} className="flex justify-between text-sm">
            <span className="text-astro-text truncate mr-2">{name}</span>
            <span className="text-astro-muted shrink-0">{count}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

export function AggregateView({ aggregates }: AggregateViewProps): React.ReactElement {
  const a = aggregates

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <StatCard label="Total Files" value={a.totalFiles} accent />
        <StatCard label="Total Size" value={formatSize(a.totalSizeBytes)} />
        <StatCard label="Total Exposure" value={formatExposure(a.totalExposureSec)} />
        <StatCard label="Avg Exposure" value={a.avgExposureSec ? formatExposure(a.avgExposureSec) : '-'} />
        <StatCard label="Targets" value={a.uniqueObjects.length} />
        <StatCard label="Filters" value={a.uniqueFilters.length} />
        <StatCard label="Stacked" value={a.stackedCount} />
        <StatCard label="Individual" value={a.individualCount} />
      </div>

      {a.dateRange.earliest && (
        <div className="text-sm text-astro-muted">
          Date range: <span className="text-astro-text">{a.dateRange.earliest}</span> to <span className="text-astro-text">{a.dateRange.latest}</span>
          {a.avgCcdTemp !== null && (
            <span className="ml-4">Avg CCD temp: <span className="text-astro-text">{a.avgCcdTemp.toFixed(1)}&deg;C</span></span>
          )}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        <BreakdownCard title="Files by Folder" data={a.filesByFolder} />
        <BreakdownCard title="Files by Object" data={a.filesByObject} />
        <BreakdownCard title="Files by Filter" data={a.filesByFilter} />
        <BreakdownCard title="Files by Type" data={a.filesByImageType} />
