Write {"file_path":"D:\code\astrorepo\src\renderer\components\fits\FileTable.tsx","content":"import React, { useState, useEffect } from 'react'
import { invoke } from '../../hooks/useIPC'
import type { FitsFileSummary } from '@shared/types'

interface FileTableProps {
  scanId: string
  onSelectFile: (fileId: string) => void
  selectedFileId: string | null
}

type SortCol = 'file_name' | 'date_obs' | 'exposure_sec' | 'object_name' | 'filter' | 'file_size_bytes' | 'folder_name'

function formatSize(bytes: number): string {
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export function FileTable({ scanId, onSelectFile, selectedFileId }: FileTableProps): React.ReactElement {
  const [files, setFiles] = useState<FitsFileSummary[]>([])
  const [total, setTotal] = useState(0)
  const [page, setPage] = useState(0)
  const [sortBy, setSortBy] = useState<SortCol>('file_name')
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc')
  const [filterFolder, setFilterFolder] = useState('')
  const [filterObj, setFilterObj] = useState('')
  const [filterType, setFilterType] = useState('')
  const [filterFilter, setFilterFilter] = useState('')
  const [folders, setFolders] = useState<string[]>([])
  const [objects, setObjects] = useState<string[]>([])
  const [filters, setFilters] = useState<string[]>([])
  const [types, setTypes] = useState<string[]>([])
  const limit = 50

  useEffect(() => {
    invoke<{ totalFiles: number; uniqueObjects: string[]; uniqueFilters: string[]; uniqueFolders: string[]; filesByImageType: Record<string, number> }>(
      'fits:scan-aggregates', { scan_id: scanId }
    ).then((agg) => {
      setObjects(agg.uniqueObjects)
      setFilters(agg.uniqueFilters)
      setFolders(agg.uniqueFolders)
      setTypes(Object.keys(agg.filesByImageType))
    })
  }, [scanId])

  useEffect(() => {
    loadFiles()
  }, [scanId, page, sortBy, sortDir, filterFolder, filterObj, filterType, filterFilter])

  async function loadFiles(): Promise<void> {
    const params: Record<string, unknown> = {
      scan_id: scanId,
      limit,
      offset: page * limit,
      sort_by: sortBy,
      sort_dir: sortDir
    }
    if (filterFolder) params.filter_folder = filterFolder
    if (filterObj) params.filter_object = filterObj
    if (filterType) params.filter_image_type = filterType
    if (filterFilter) params.filter_filter = filterFilter

    const result = await invoke<{ files: FitsFileSummary[]; total: number }>('fits:list-files', params)
    setFiles(result.files)
    setTotal(result.total)
  }

  function handleSort(col: SortCol): void {
    if (sortBy === col) {
      setSortDir(d => d === 'asc' ? 'desc' : 'asc')
    } else {
      setSortBy(col)
      setSortDir('asc')
    }
    setPage(0)
  }

  function sortIndicator(col: SortCol): string {
    if (sortBy !== col) return ''
    return sortDir === 'asc' ? ' ↑' : ' ↓'
  }

  const totalPages = Math.ceil(total / limit)

  return (
    <div className="bg-astro-surface border border-astro-border rounded-lg overflow-hidden">
      <div className="px-4 py-3 border-b border-astro-border flex flex-wrap gap-2 items-center">
        <span className="text-sm text-astro-muted">{total} files</span>
        <select value={filterFolder} onChange={e => { setFilterFolder(e.target.value); setPage(0) }} className="bg-astro-bg border border-astro-border rounded px-2 py-1 text-sm text-astro-text">
          <option value="">All folders</option>
          {folders.map(f => <option key={f} value={f}>{f}</option>)}
        </select>
        <select value={filterObj} onChange={e => { setFilterObj(e.target.value); setPage(0) }} className="bg-astro-bg border border-astro-border rounded px-2 py-1 text-sm text-astro-text">
          <option value="">All objects</option>
          {objects.map(o => <option key={o} value={o}>{o}</option>)}
        </select>
        <select value={filterType} onChange={e => { setFilterType(e.target.value); setPage(0) }} className="bg-astro-bg border border-astro-border rounded px-2 py-1 text-sm text-astro-text">
          <option value="">All types</option>
          {types.map(t => <option key={t} value={t}>{t}</option>)}
        </select>
        <select value={filterFilter} onChange={e => { setFilterFilter(e.target.value); setPage(0) }} className="bg-astro-bg border border-astro-border rounded px-2 py-1 text-sm text-astro-text">
          <option value="">All filters</option>
          {filters.map(f => <option key={f} value={f}>{f}</option>)}
        </select>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs text-astro-muted uppercase tracking-wider border-b border-astro-border">
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('file_name')}>File{sortIndicator('file_name')}</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('folder_name')}>Folder{sortIndicator('folder_name')}</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('object_name')}>Object{sortIndicator('object_name')}</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('filter')}>Filter{sortIndicator('filter')}</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('exposure_sec')}>Exp{sortIndicator('exposure_sec')}</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('date_obs')}>Date{sortIndicator('date_obs')}</th>
              <th className="px-4 py-2">Type</th>
              <th className="px-4 py-2 cursor-pointer hover:text-astro-text" onClick={() => handleSort('file_size_bytes')}>Size{sortIndicator('file_size_bytes')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-astro-border/50">
            {files.map((f) => (
              <tr
                key={f.id}
                onClick={() => onSelectFile(f.id)}
                className={`cursor-pointer transition-colors ${
                  selectedFileId === f.id ? 'bg-astro-accent/10' : 'hover:bg-astro-bg/50'
                }`}
              >
                <td className="px-4 py-2 text-astro-text truncate max-w-[200px]">{f.fileName}</td>
                <td className="px-4 py-2 text-astro-muted truncate max-w-[120px]">{f.folderName ?? '-'}</td>
                <td className="px-4 py-2 text-astro-text">{f.objectName ?? '-'}</td>
                <td className="px-4 py-2 text-astro-muted">{f.filter ?? '-'}</td>
                <td className="px-4 py-2 text-astro-muted">{f.exposureSec != null ? `${f.exposureSec}s` : '-'}</td>
                <td className="px-4 py-2 text-astro-muted truncate max-w-[140px]">{f.dateObs ?? '-'}</td>
                <td className="px-4 py-2">
                  <div className="flex gap-1">
                    {f.imageType && <span className="text-xs px-1.5 py-0.5 rounded bg-astro-bg text-astro-muted">{f.imageType}</span>}
                    {f.isStacked && <span className="text-xs px-1.5 py-0.5 rounded bg-astro-accent/20 text-astro-accent">stacked</span>}
                  </div>
                </td>
                <td className="px-4 py-2 text-astro-muted">{formatSize(f.fileSizeBytes)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {totalPages > 1 && (
        <div className="px-4 py-3 border-t border-astro-border flex items-center justify-between">
          <button
            onClick={() => setPage(p => Math.max(0, p - 1))}
            disabled={page === 0}
            className="text-sm text-astro-muted hover:text-astro-text disabled:opacity-50"
          >
            Previous
          </button>
          <span className="text-sm text-astro-muted">Page {page + 1} of {totalPages}</span>
          <button
            onClick={() => setPage(p => Math.min(totalPages - 1, p + 1))}
            disabled={page >= totalPages - 1}
            className="text-sm text-astro-muted hover:text-astro-text disabled:opacity-50"
          >
            Next
          </button>
        </div>
      )}
    </div>
  )
}
"}

Write {"file_path":"D:\code\astrorepo\src\renderer\pages\FitsAnalyzer.tsx","content":"import React, { useState, useEffect } from 'react'
import { PageContainer } from '../components/common/PageContainer'
import { ScanControls } from '../components/fits/ScanControls'
import { ScanHistory } from '../components/fits/ScanHistory'
import { AggregateView } from '../components/fits/AggregateView'
import { FileTable } from '../components/fits/FileTable'
import { FileDetail } from '../components/fits/FileDetail'
import { invoke } from '../hooks/useIPC'
import type { FitsScanSummary, FitsScanAggregates } from '@shared/types'

export function FitsAnalyzer(): React.ReactElement {
  const [scans, setScans] = useState<FitsScanSummary[]>([])
  const [selectedScanId, setSelectedScanId] = useState<string | null>(null)
  const [selectedFileId, setSelectedFileId] = useState<string | null>(null)
  const [aggregates, setAggregates] = useState<FitsScanAggregates | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    loadScans()
  }, [])

  useEffect(() => {
    if (selectedScanId) {
      invoke<FitsScanAggregates>('fits:scan-aggregates', { scan_id: selectedScanId }).then(setAggregates)
    } else {
      setAggregates(null)
    }
    setSelectedFileId(null)
  }, [selectedScanId])

  async function loadScans(): Promise<void> {
    setLoading(true)
    const result = await invoke<{ scans: FitsScanSummary[]; total: number }>('fits:list-scans', { limit: 50 })
    setScans(result.scans)
    if (result.scans.length > 0 && !selectedScanId) {
      setSelectedScanId(result.scans[0].id)
    }
    setLoading(false)
  }

  function handleScanComplete(): void {
    loadScans()
  }

  function handleSelectScan(id: string): void {
    setSelectedScanId(id)
  }

  if (loading) {
    return (
      <PageContainer title="FITS Analyzer">
        <div className="text-astro-muted">Loading...</div>
      </PageContainer>
    )
  }

  return (
    <PageContainer title="FITS Analyzer" subtitle="Scan and analyze FITS file metadata across your astrophotography folders">
      <div className="space-y-4">
        <ScanControls onScanComplete={handleScanComplete} />

        <ScanHistory
          scans={scans}
          selectedScanId={selectedScanId}
          onSelectScan={handleSelectScan}
          onRefresh={loadScans}
        />

        {selectedScanId && aggregates && (
          <div className="space-y-4">
            <AggregateView aggregates={aggregates} />

            <FileTable
              scanId={selectedScanId}
              onSelectFile={setSelectedFileId}
              selectedFileId={selectedFileId}
            />

            {selectedFileId && (
              <FileDetail
                fileId={selectedFileId}
                onClose={() => setSelectedFileId(null)}
              />
            )}
          </div>
        )}
      </div>
    </PageContainer>
  )
}
"}

Write {"file_path":"D:\code\astrorepo\tests\unit\fits-parser.test.ts","content":"import { describe, it, expect, afterEach } from 'vitest'
import fs from 'fs'
import path from 'path'
import os from 'os'
import { parseFitsFile, parseFitsHeaders, computeImageStats } from '../../src/main/fits/parser'

const BLOCK_SIZE = 2880
const RECORD_SIZE = 80

function padRecord(content: string): string {
  return content.padEnd(RECORD_SIZE, ' ')
}

function buildFitsFile(records: string[], pixelData?: Buffer): string {
  const headerRecords = records.map(padRecord)
  headerRecords.push(padRecord('END'))

  const headerBytes = headerRecords.join('')
  const headerBlockCount = Math.ceil(headerBytes.length / BLOCK_SIZE)
  const paddedHeader = headerBytes.padEnd(headerBlockCount * BLOCK_SIZE, ' ')

  const filePath = path.join(os.tmpdir(), `test-${Date.now()}-${Math.random().toString(36).slice(2)}.fits`)
  const headerBuf = Buffer.from(paddedHeader, 'ascii')

  if (pixelData) {
    const dataPadded = Buffer.alloc(Math.ceil(pixelData.length / BLOCK_SIZE) * BLOCK_SIZE)
    pixelData.copy(dataPadded)
    fs.writeFileSync(filePath, Buffer.concat([headerBuf, dataPadded]))
  } else {
    fs.writeFileSync(filePath, headerBuf)
  }

  return filePath
}

let tempFiles: string[] = []

afterEach(() => {
  for (const f of tempFiles) {
    try { fs.unlinkSync(f) } catch { /* ignore */ }
  }
  tempFiles = []
})

function createTemp(records: string[], pixelData?: Buffer): string {
  const p = buildFitsFile(records, pixelData)
  tempFiles.push(p)
  return p
}

describe('FITS Parser', () => {
  it('parses a minimal valid FITS header', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T / Standard FITS",
      "BITPIX  =                   16 / Bits per pixel",
      "NAXIS   =                    0 / No data"
    ])

    const result = parseFitsFile(filePath)
    expect(result.isValid).toBe(true)
    expect(result.headerMap.get('SIMPLE')?.value).toBe(true)
    expect(result.headerMap.get('BITPIX')?.value).toBe(16)
    expect(result.headerMap.get('NAXIS')?.value).toBe(0)
    expect(result.imageStats).toBeNull()
  })

  it('parses string values with single quotes', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0",
      "OBJECT  = 'M31 Andromeda   ' / Target name"
    ])

    const result = parseFitsFile(filePath)
    expect(result.headerMap.get('OBJECT')?.value).toBe('M31 Andromeda')
    expect(result.headerMap.get('OBJECT')?.comment).toBe('Target name')
  })

  it('parses numeric values', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0",
      "EXPTIME =              300.000 / Exposure time in seconds",
      "CCD-TEMP=              -10.500 / CCD temperature"
    ])

    const result = parseFitsFile(filePath)
    expect(result.headerMap.get('EXPTIME')?.value).toBe(300)
    expect(result.headerMap.get('CCD-TEMP')?.value).toBe(-10.5)
  })

  it('parses boolean values', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T / true",
      "BITPIX  =                   16",
      "NAXIS   =                    0",
      "EXTEND  =                    F / no extensions"
    ])

    const result = parseFitsFile(filePath)
    expect(result.headerMap.get('SIMPLE')?.value).toBe(true)
    expect(result.headerMap.get('EXTEND')?.value).toBe(false)
  })

  it('parses COMMENT and HISTORY records', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0",
      "COMMENT  This is a comment record",
      "HISTORY  Processed with PixInsight"
    ])

    const result = parseFitsFile(filePath)
    const comments = result.headers.filter(h => h.keyword === 'COMMENT')
    expect(comments.length).toBe(1)
    expect(comments[0].comment).toContain('This is a comment record')

    const history = result.headers.filter(h => h.keyword === 'HISTORY')
    expect(history.length).toBe(1)
    expect(history[0].comment).toContain('Processed with PixInsight')
  })

  it('rejects files without SIMPLE = T', () => {
    const filePath = createTemp([
      "SIMPLE  =                    F",
      "BITPIX  =                   16",
      "NAXIS   =                    0"
    ])

    const result = parseFitsFile(filePath)
    expect(result.isValid).toBe(false)
    expect(result.error).toContain('SIMPLE')
  })

  it('computes image statistics for 16-bit data', () => {
    const naxis1 = 4
    const naxis2 = 2
    const pixelBuf = Buffer.alloc(naxis1 * naxis2 * 2)
    const values = [100, 200, 300, 400, 500, 600, 700, 800]
    values.forEach((v, i) => pixelBuf.writeInt16BE(v, i * 2))

    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    2",
      `NAXIS1  =                    ${naxis1}`,
      `NAXIS2  =                    ${naxis2}`
    ], pixelBuf)

    const result = parseFitsFile(filePath)
    expect(result.isValid).toBe(true)
    expect(result.imageStats).not.toBeNull()
    expect(result.imageStats!.min).toBe(100)
    expect(result.imageStats!.max).toBe(800)
    expect(result.imageStats!.mean).toBe(450)
    expect(result.imageStats!.stddev).toBeCloseTo(229.13, 1)
  })

  it('applies BSCALE and BZERO correctly', () => {
    const naxis1 = 2
    const naxis2 = 1
    const pixelBuf = Buffer.alloc(naxis1 * naxis2 * 2)
    pixelBuf.writeInt16BE(100, 0)
    pixelBuf.writeInt16BE(200, 2)

    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    2",
      `NAXIS1  =                    ${naxis1}`,
      `NAXIS2  =                    ${naxis2}`,
      "BSCALE  =                  2.0",
      "BZERO   =                 1000"
    ], pixelBuf)

    const result = parseFitsFile(filePath)
    expect(result.imageStats).not.toBeNull()
    expect(result.imageStats!.min).toBe(100 * 2 + 1000)
    expect(result.imageStats!.max).toBe(200 * 2 + 1000)
  })

  it('computes stats for 32-bit float data', () => {
    const naxis1 = 3
    const naxis2 = 1
    const pixelBuf = Buffer.alloc(naxis1 * naxis2 * 4)
    pixelBuf.writeFloatBE(1.5, 0)
    pixelBuf.writeFloatBE(2.5, 4)
    pixelBuf.writeFloatBE(3.5, 8)

    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                  -32",
      "NAXIS   =                    2",
      `NAXIS1  =                    ${naxis1}`,
      `NAXIS2  =                    ${naxis2}`
    ], pixelBuf)

    const result = parseFitsFile(filePath)
    expect(result.imageStats).not.toBeNull()
    expect(result.imageStats!.min).toBeCloseTo(1.5, 1)
    expect(result.imageStats!.max).toBeCloseTo(3.5, 1)
    expect(result.imageStats!.mean).toBeCloseTo(2.5, 1)
  })

  it('handles a header spanning multiple blocks', () => {
    const records: string[] = [
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0"
    ]
    for (let i = 0; i < 40; i++) {
      records.push(`KEY${String(i).padStart(4, '0')} =                    ${i}`)
    }

    const filePath = createTemp(records)
    const result = parseFitsFile(filePath)
    expect(result.isValid).toBe(true)
    expect(result.headers.length).toBe(43)
    expect(result.headerMap.get('KEY0039')?.value).toBe(39)
  })

  it('handles embedded single quotes in string values', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0",
      "OBJECT  = 'NGC 7000 ''North America'' Nebula'"
    ])

    const result = parseFitsFile(filePath)
    expect(result.headerMap.get('OBJECT')?.value).toBe("NGC 7000 'North America' Nebula")
  })

  it('returns null imageStats when NAXIS is 0', () => {
    const filePath = createTemp([
      "SIMPLE  =                    T",
      "BITPIX  =                   16",
      "NAXIS   =                    0"
    ])

    const result = parseFitsFile(filePath)
    expect(result.imageStats).toBeNull()
  })
})
"}

Write {"file_path":"D:\code\astrorepo\tests\unit\fits-stacking.test.ts","content":"import { describe, it, expect } from 'vitest'
import { detectStacking } from '../../src/main/fits/stacking'
import type { FitsHeaderRecord } from '../../src/main/fits/parser'

function makeHeaderMap(entries: Record<string, string | number | boolean>): Map<string, FitsHeaderRecord> {
  const map = new Map<string, FitsHeaderRecord>()
  for (const [keyword, value] of Object.entries(entries)) {
    map.set(keyword, { keyword, value, comment: null, raw: '' })
  }
  return map
}

describe('Stacking Detection', () => {
  it('detects stacking via NCOMBINE', () => {
    const result = detectStacking(makeHeaderMap({ NCOMBINE: 50 }))
    expect(result.isStacked).toBe(true)
    expect(result.ncombine).toBe(50)
    expect(result.evidence).toContain('NCOMBINE=50')
  })

  it('detects stacking via STACKCNT', () => {
    const result = detectStacking(makeHeaderMap({ STACKCNT: 25 }))
    expect(result.isStacked).toBe(true)
    expect(result.ncombine).toBe(25)
  })

  it('detects stacking via IMAGETYP containing master', () => {
    const result = detectStacking(makeHeaderMap({ IMAGETYP: 'Master Dark' }))
    expect(result.isStacked).toBe(true)
    expect(result.evidence.some(e => e.includes('Master Dark'))).toBe(true)
  })

  it('detects stacking via IMAGETYP containing stacked', () => {
    const result = detectStacking(makeHeaderMap({ IMAGETYP: 'Stacked Light' }))
    expect(result.isStacked).toBe(true)
  })

  it('detects stacking via CALSTAT', () => {
    const result = detectStacking(makeHeaderMap({ CALSTAT: 'BDF' }))
    expect(result.isStacked).toBe(true)
    expect(result.calstat).toBe('BDF')
  })

  it('detects stacking via TOTALEXP differing from EXPTIME', () => {
    const result = detectStacking(makeHeaderMap({ EXPTIME: 300, TOTALEXP: 9000 }))
    expect(result.isStacked).toBe(true)
    expect(result.totalExposure).toBe(9000)
  })

  it('does not flag a normal light frame as stacked', () => {
    const result = detectStacking(makeHeaderMap({
      IMAGETYP: 'Light',
      EXPTIME: 300,
      BITPIX: 16
    }))
    expect(result.isStacked).toBe(false)
    expect(result.evidence).toHaveLength(0)
  })

  it('does not flag NCOMBINE=1 as stacked', () => {
    const result = detectStacking(makeHeaderMap({ NCOMBINE: 1 }))
    expect(result.isStacked).toBe(false)
  })

  it('accumulates multiple evidence signals', () => {
    const result = detectStacking(makeHeaderMap({
      NCOMBINE: 30,
      CALSTAT: 'BDF',
      IMAGETYP: 'Master Light'
    }))
    expect(result.isStacked).toBe(true)
    expect(result.evidence.length).toBeGreaterThanOrEqual(3)
  })
})
"}

