function PhaseRow({ phase }: { phase: HomeScanPhaseProgress }): React.ReactElement {
  const icon = phase.status === 'complete' ? '✓'
    : phase.status === 'pending' ? '○'
    : '◌'
  const statusText = phase.status === 'discovering' ? 'discovering folders...'
    : phase.status === 'scanning_fits' ? 'parsing FITS metadata...'
    : phase.status === 'complete' ? `${phase.foldersFound} targets`
    : ''
  return (
    <div className="flex items-center gap-2 text-xs">
      <span className={phase.status === 'complete' ? 'text-green-400' : phase.status === 'pending' ? 'text-astro-muted' : 'text-astro-accent'}>
        {icon}
      </span>
      <span className={phase.status === 'pending' ? 'text-astro-muted' : 'text-astro-text'}>
        {phase.name.charAt(0).toUpperCase() + phase.name.slice(1)}
      </span>
      {statusText && <span className="text-astro-muted">— {statusText}</span>}
    </div>
  )
}

function ExpandedSubfolders({ label, subfolders, totalFiles }: {
  label: string
  subfolders: Array<{ name: string | null; path: string; fileCount: number }>
  totalFiles: number
}): React.ReactElement | null {
  if (totalFiles === 0) return null
  return (
    <div className="mb-2 last:mb-0">
      <p className="text-[11px] text-astro-muted font-medium uppercase tracking-wide mb-0.5">
        {label} ({totalFiles} files)
      </p>
      <div className="space-y-0.5 pl-2">
        {subfolders.map((sf, i) => (
          <div key={i} className="flex items-center justify-between text-[11px]">
            <span className="text-astro-text font-mono">{sf.name ?? '(root)'}/</span>
            <div className="flex items-center gap-2">
              <span className="text-astro-muted">{sf.fileCount} files</span>
              <button
                onClick={(e) => {
                  e.stopPropagation()
                  invoke('home:open-folder', { folder_path: sf.path })
                }}
                className="p-0.5 text-astro-muted hover:text-astro-accent transition-colors"
                title="Open in file explorer"
              >
                <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" />
                </svg>
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}"}

